    """Materi lama diberi nomor urut per kelas-mapel sesuai tanggal dibuat (yang lama = Materi 1)."""
    Material = apps.get_model("materials", "Material")
    counters = {}
    for material in Material.objects.order_by("teaching_assignment_id", "created_at", "id"):
        counters[material.teaching_assignment_id] = counters.get(material.teaching_assignment_id, 0) + 1
        material.order = counters[material.teaching_assignment_id]
        material.save(update_fields=["order"])


